from ortools.linear_solver import pywraplp
import json

def main():
    aircraft_names = ["AA101", "UA205", "DL318", "SW442", "JB556", 
                      "NK677", "B6789", "AS890", "F9123", "WN456"]
    N = len(aircraft_names)

    E = [129, 195, 89, 96, 110, 120, 124, 126, 135, 160]
    T = [155, 258, 98, 106, 123, 135, 138, 140, 150, 180]
    L = [559, 744, 510, 521, 555, 576, 577, 573, 591, 657]
    C = [10, 10, 30, 30, 30, 30, 30, 30, 30, 30]

    num_runways = 2

    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        result = {
            "landing_times": [],
            "runways": [],
            "total_penalty": None
        }
        print(json.dumps(result))
        return

    INF = solver.infinity()

    t = {}
    x = {}
    y = {}

    for i in range(N):
        t[i] = solver.NumVar(E[i], L[i], f"t_{i}")

        for k in range(num_runways):
            x[(i, k)] = solver.BoolVar(f"x_{i}_{k}")

        solver.Add(sum(x[(i, k)] for k in range(num_runways)) == 1)

    for i in range(N):
        for j in range(N):
            if i != j:
                y[(i, j)] = solver.BoolVar(f"y_{i}_{j}")

    S = {}
    large_aircraft = {0, 1}

    for i in range(N):
        for j in range(N):
            if i != j:
                if i in large_aircraft and j in large_aircraft:
                    S[(i, j)] = 3
                elif i in large_aircraft or j in large_aircraft:
                    S[(i, j)] = 15
                else:
                    S[(i, j)] = 8

    M = max(L) - min(E) + max(S.values())

    for i in range(N):
        for j in range(N):
            if i != j:
                for k in range(num_runways):
                    solver.Add(y[(i, j)] <= x[(i, k)] + (1 - x[(j, k)]))
                    solver.Add(y[(i, j)] <= x[(j, k)] + (1 - x[(i, k)]))

    for i in range(N):
        for j in range(N):
            if i < j:
                same_runway = solver.BoolVar(f"same_{i}_{j}")

                for k in range(num_runways):
                    solver.Add(same_runway >= x[(i, k)] + x[(j, k)] - 1)

                solver.Add(y[(i, j)] + y[(j, i)] >= same_runway)

                solver.Add(y[(i, j)] <= same_runway)
                solver.Add(y[(j, i)] <= same_runway)

    for i in range(N):
        for j in range(N):
            if i != j:
                solver.Add(t[j] >= t[i] + S[(i, j)] - M * (1 - y[(i, j)]))

    early = {}
    late = {}
    for i in range(N):
        early[i] = solver.NumVar(0, INF, f"early_{i}")
        late[i] = solver.NumVar(0, INF, f"late_{i}")

        solver.Add(t[i] - T[i] == late[i] - early[i])

    total_penalty = solver.Sum(C[i] * (early[i] + late[i]) for i in range(N))
    solver.Minimize(total_penalty)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        landing_times = [int(round(t[i].solution_value())) for i in range(N)]
        runways = []
        for i in range(N):
            for k in range(num_runways):
                if x[(i, k)].solution_value() > 0.5:
                    runways.append(k + 1)
                    break
        total_penalty_value = int(round(solver.Objective().Value()))
        result = {
            "landing_times": landing_times,
            "runways": runways,
            "total_penalty": total_penalty_value
        }
    else:
        result = {
            "landing_times": [],
            "runways": [],
            "total_penalty": None
        }
    print(json.dumps(result))

if __name__ == "__main__":
    main()
